package value

import (
	"fmt"
	"reflect"
	"strings"
)

// DecodeValue decodes v into dst, a non nil pointer to a type generated by
// the go generator, e.g. a structured annotation: struct fields are matched
// by their thrift name, enums and integers are decoded from integer values
// and bools from bool or integer values, the bool constants of the IDL being
// integers.
func DecodeValue(v *Value, dst any) error {
	rv := reflect.ValueOf(dst)

	if rv.Kind() != reflect.Pointer || rv.IsNil() {
		return fmt.Errorf("value: %T is not a non nil pointer", dst)
	}

	return decodeValue(v, rv.Elem())
}

func decodeValue(v *Value, rv reflect.Value) error {
	if v == nil || v.NullValue != nil {
		rv.Set(reflect.Zero(rv.Type()))

		return nil
	}

	switch rv.Kind() {
	case reflect.Pointer:
		if rv.IsNil() {
			rv.Set(reflect.New(rv.Type().Elem()))
		}

		return decodeValue(v, rv.Elem())
	case reflect.Bool:
		return decodeBool(v, rv)
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return decodeInt(v, rv)
	case reflect.Float32, reflect.Float64:
		return decodeFloat(v, rv)
	case reflect.String:
		return decodeString(v, rv)
	case reflect.Slice:
		return decodeSlice(v, rv)
	case reflect.Map:
		return decodeMap(v, rv)
	case reflect.Struct:
		return decodeStruct(v, rv)
	}

	return mismatch(v, rv)
}

func decodeInt(v *Value, rv reflect.Value) error {
	if v.IntegerValue == nil {
		return mismatch(v, rv)
	}

	if rv.OverflowInt(*v.IntegerValue) {
		return fmt.Errorf("value: %d overflows %s", *v.IntegerValue, rv.Type())
	}

	rv.SetInt(*v.IntegerValue)

	return nil
}

func decodeFloat(v *Value, rv reflect.Value) error {
	switch {
	case v.DoubleValue != nil:
		rv.SetFloat(*v.DoubleValue)
	case v.IntegerValue != nil:
		rv.SetFloat(float64(*v.IntegerValue))
	default:
		return mismatch(v, rv)
	}

	return nil
}

func decodeString(v *Value, rv reflect.Value) error {
	switch {
	case v.StringValue != nil:
		rv.SetString(*v.StringValue)
	case v.BinaryValue != nil:
		rv.SetString(string(v.BinaryValue))
	default:
		return mismatch(v, rv)
	}

	return nil
}

func decodeBool(v *Value, rv reflect.Value) error {
	switch {
	case v.BoolValue != nil:
		rv.SetBool(*v.BoolValue)
	case v.IntegerValue != nil && (*v.IntegerValue == 0 || *v.IntegerValue == 1):
		rv.SetBool(*v.IntegerValue == 1)
	default:
		return mismatch(v, rv)
	}

	return nil
}

func decodeSlice(v *Value, rv reflect.Value) error {
	if rv.Type().Elem().Kind() == reflect.Uint8 {
		switch {
		case v.BinaryValue != nil:
			rv.SetBytes(append([]byte(nil), v.BinaryValue...))

			return nil
		case v.StringValue != nil:
			rv.SetBytes([]byte(*v.StringValue))

			return nil
		}
	}

	if v.ListValue == nil {
		return mismatch(v, rv)
	}

	s := reflect.MakeSlice(rv.Type(), len(v.ListValue.Values), len(v.ListValue.Values))

	for i, e := range v.ListValue.Values {
		if err := decodeValue(e, s.Index(i)); err != nil {
			return fmt.Errorf("value: element %d: %w", i, err)
		}
	}

	rv.Set(s)

	return nil
}

func decodeMap(v *Value, rv reflect.Value) error {
	if v.MapValue == nil {
		return mismatch(v, rv)
	}

	m := reflect.MakeMapWithSize(rv.Type(), len(v.MapValue.Entries))

	for i, e := range v.MapValue.Entries {
		var (
			k  = reflect.New(rv.Type().Key()).Elem()
			vv = reflect.New(rv.Type().Elem()).Elem()
		)

		if err := decodeValue(e.Key, k); err != nil {
			return fmt.Errorf("value: key of entry %d: %w", i, err)
		}

		if err := decodeValue(e.Value, vv); err != nil {
			return fmt.Errorf("value: value of entry %d: %w", i, err)
		}

		m.SetMapIndex(k, vv)
	}

	rv.Set(m)

	return nil
}

func decodeStruct(v *Value, rv reflect.Value) error {
	if v.StructValue == nil {
		return mismatch(v, rv)
	}

	var (
		t      = rv.Type()
		fields = make(map[string]int, t.NumField())
	)

	for i := range t.NumField() {
		if name, _, _ := strings.Cut(t.Field(i).Tag.Get("thrift"), ","); name != "" {
			fields[name] = i
		}
	}

	for name, fv := range v.StructValue.Fields {
		i, ok := fields[name]

		if !ok {
			return fmt.Errorf("value: %s has no field %q", t, name)
		}

		if err := decodeValue(fv, rv.Field(i)); err != nil {
			return fmt.Errorf("value: field %q: %w", name, err)
		}
	}

	return nil
}

func mismatch(v *Value, rv reflect.Value) error {
	return fmt.Errorf("value: can not decode a %T into a %s", v.Interface(), rv.Type())
}
